const CUT_EXPLORE_ONBOARD_PAIRS: Array<Omit<CutPair, 'stage'>> = [
  {"id":"U-visualize-box","bodies":["orbit-explore"],"kind":"removed","ruling":"R-rop2-13","before":"**Visualize**\n```\n┌─────────────────────────────────────────┐\n│     Use ASCII diagrams liberally        │\n├─────────────────────────────────────────┤\n│                                         │\n│      ┌────────┐         ┌────────┐      │\n│      │ State  │────────▶│ State  │      │\n│      │   A    │         │   B    │      │\n│      └────────┘         └────────┘      │\n│                                         │\n│   System diagrams, state machines,      │\n│   data flows, architecture sketches,    │\n│   dependency graphs, comparison tables  │\n│                                         │\n└─────────────────────────────────────────┘\n```\n\n**Surface risks and unknowns**","after":"**Surface risks and unknowns**","phrase":"Use ASCII diagrams liberally        │"},
  {"id":"U-entry-points","bodies":["orbit-explore"],"kind":"removed","ruling":"R-rop2-13","before":"## Handling Different Entry Points\n\n**User brings a vague idea:**\n```\nUser: I'm thinking about adding real-time collaboration\n\nYou: Real-time collab is a big space. Let me think about this...\n\n      COLLABORATION SPECTRUM\n      ════════════════════════════════════════════\n\n      Awareness          Coordination         Sync\n          │                   │                 │\n          ▼                   ▼                 ▼\n      ┌────────┐         ┌────────┐        ┌────────┐\n      │Presence│         │Cursors │        │  CRDT  │\n      │  \"3    │         │ Multi  │        │Conflict│\n      │online\" │         │ select │        │  free  │\n      └────────┘         └────────┘        └────────┘\n          │                   │                 │\n       trivial            moderate           complex\n\n      Where's your head at?\n```\n\n**User brings a specific problem:**\n```\nUser: The auth system is a mess\n\nYou: [reads codebase]\n\n     ┌─────────────────────────────────────────────┐\n     │              CURRENT AUTH FLOW              │\n     └─────────────────────────────────────────────┘\n                        │\n          ┌─────────────┼─────────────┐\n          ▼             ▼             ▼\n     ┌─────────┐  ┌─────────┐  ┌─────────┐\n     │ Google  │  │  GitHub │  │  Email  │\n     │  OAuth  │  │  OAuth  │  │  Magic  │\n     └────┬────┘  └────┬────┘  └────┬────┘\n          │             │             │\n          └─────────────┼─────────────┘\n                        ▼\n                  ┌───────────┐\n                  │  Session  │\n                  └─────┬─────┘\n                        │\n                        ▼\n                  ┌───────────┐\n                  │   Perms   │\n                  └───────────┘\n\n     I see three tangles. Which one's burning?\n```\n\n**User is stuck mid-implementation:**\n```\nUser: /orbit:explore add-auth-system\n      The OAuth integration is more complex than expected\n\nYou: [reads change artifacts]\n\n     You're on task 4: \"Implement OAuth flow\"\n\n     Let me trace what's involved...\n\n     [draws diagram, explores options, suggests paths]\n\n     Want to update the design to reflect this?\n     Or add a spike task to investigate?\n```\n\n**User wants to compare options:**\n```\nUser: Should we use Postgres or SQLite?\n\nYou: Generic answer is boring. What's the context?\n\nUser: A CLI tool that tracks local dev environments\n\nYou: That changes everything.\n\n     ┌─────────────────────────────────────────────────┐\n     │          CLI TOOL DATA STORAGE                  │\n     └─────────────────────────────────────────────────┘\n\n     Key constraints:\n     • No daemon running\n     • Must work offline\n     • Single user\n\n                  SQLite          Postgres\n     Deployment   embedded ✓      needs server ✗\n     Offline      yes ✓           no ✗\n     Single file  yes ✓           no ✗\n\n     SQLite. Not even close.\n\n     Unless... is there a sync component?\n```\n\n---\n\n## Ending Discovery","after":"## Ending Discovery","phrase":"COLLABORATION SPECTRUM"},
  {"id":"U-summary-template","bodies":["orbit-explore"],"kind":"removed","ruling":"R-rop2-13","before":"you might summarize:\n\n```\n## What We Figured Out\n\n**The problem**: [crystallized understanding]\n\n**The approach**: [if one emerged]\n\n**Open questions**: [if any remain]\n\n**Next steps** (if ready):\n- Create a change proposal\n- Keep exploring: just keep talking\n```\n\nBut this summary is optional.","after":"you might summarize: But this summary is optional.","phrase":"## What We Figured Out"},
  {"id":"U-summary-joined","bodies":["orbit-explore"],"kind":"reworded","before":"When it feels like things are crystallizing, you might summarize: But this summary is optional.","after":"When it feels like things are crystallizing, you might summarize what you figured out, but this summary is optional."},
  {"id":"U-guardrail-implement","bodies":["orbit-explore"],"kind":"restated","before":"## Guardrails\n\n- **Don't implement** - Never write code or implement features. Creating orbit artifacts is fine, writing application code is not.\n- **Don't fake understanding**","after":"## Guardrails\n\n- **Don't fake understanding**","steps":["**IMPORTANT: Explore mode is for thinking, not implementing.**"]},
  {"id":"U-guardrail-rush-structure","bodies":["orbit-explore"],"kind":"restated","before":"dig deeper\n- **Don't rush** - Discovery is thinking time, not task time\n- **Don't force structure** - Let patterns emerge naturally\n- **Don't auto-capture**","after":"dig deeper\n- **Don't auto-capture**","steps":["**Patient** - Don't rush to conclusions, let the shape of the problem emerge"]},
  {"id":"U-guardrail-visualize","bodies":["orbit-explore"],"kind":"restated","before":"don't just do it\n- **Do visualize** - A good diagram is worth many paragraphs\n- **Do explore the codebase**","after":"don't just do it\n- **Do explore the codebase**","steps":["**Visual** - Use ASCII diagrams liberally when they'd help clarify thinking"]},
  {"id":"U-guardrail-codebase","bodies":["orbit-explore"],"kind":"restated","before":"don't just do it\n- **Do explore the codebase** - Ground discussions in reality\n- **Do question assumptions**","after":"don't just do it\n- **Do question assumptions**","steps":["**Grounded** - Explore the actual codebase when relevant"]},
  {"id":"E-ptr-closure-composition","bodies":["orbit-explore"],"kind":"reworded","before":"carries it into spec text at promotion (see \"Composition with /orbit:propose\").","after":"carries it into spec text at promotion (the body's \"Composition with `/orbit:propose`\")."},
  {"id":"E-ptr-conclude-sweep","bodies":["orbit-explore"],"kind":"reworded","before":"1. the boundary residency sweep (below, under \"Run-summary emit\");","after":"1. the boundary residency sweep (the body's \"Run-summary emit\");"},
  {"id":"E-ptr-engine-crystallization","bodies":["orbit-explore"],"kind":"reworded","before":"Bare-mode `/orbit:explore` does NOT emit — see \"Crystallization to named change\" below.","after":"Bare-mode `/orbit:explore` does NOT emit — see the body's \"Crystallization to named change\"."},
  {"id":"E-ptr-crystallization-begin","bodies":["orbit-explore"],"kind":"reworded","before":"(2) THEN fire the BEGIN emit per the mode-aware rules above — the engine","after":"(2) THEN fire the BEGIN emit as the body's \"BEGIN emit\" says — the engine"},
  {"id":"E-ptr-crystallization-conclude","bodies":["orbit-explore"],"kind":"reworded","before":"an exploration that will build nothing is CONCLUDED in place (see \"Concluding an exploration\"), not deleted.\n\n**Confirmation gate**","after":"an exploration that will build nothing is CONCLUDED in place (the body's \"Concluding an exploration\"), not deleted.\n\n**Confirmation gate**"},
  {"id":"E-ptr-scaffold-grammar","bodies":["orbit-explore"],"kind":"reworded","before":"keyed by the rule's ID, in the entry grammar below: the domain","after":"keyed by the rule's ID, in the entry grammar of `references/mechanism-entries.md`: the domain"},
  {"id":"E-ptr-modeB-below","bodies":["orbit-explore"],"kind":"reworded","before":"AND the minimal `.openspec.yaml` (see below).","after":"AND the minimal `.openspec.yaml` (`references/new-exploration.md`)."},
  {"id":"E-timing-twice","bodies":["orbit-explore"],"kind":"reworded","before":"Named-mode `/orbit:explore <name>` emits TWICE per session shape (D-arc Stage D3): once at BEGIN and once at each conversation boundary.","after":"Named-mode `/orbit:explore <name>` emits at BEGIN and at each conversation boundary."},
  {"id":"E-timing-sweep","bodies":["orbit-explore"],"kind":"reworded","before":"**Boundary residency sweep — \"no emit without sweep\"** (D-arc Stage D5, leak-hardening layer 2; begin emits excepted — nothing has been discussed yet): before EVERY boundary emit, sweep the conversation since the last emit for decisions, leanings, rejections, and citations that are not yet file-resident, and write each into its slot — Decisions (with the entry's ID opener and `Kind:`) / a rule's Mechanism entry (its domain table, its closure token and residual slots, or a move's disposition) / an open question's `Standing recommendation:` / Considered & out / References — BEFORE invoking the emit. A rule whose domain, closure or a move disposition was settled in conversation and whose entry does not yet carry it is written into the entry before the emit; a rule left with no entry stays a visible open domain (per the \"A rule is captured\" section-evolution rule). The sweep rides this existing boundary trigger — no new prompt, no user-facing step — so the engine-computed attestation counts describe the SWEPT file, and `orbit-audit-drift`'s cross-check closes the loop.","after":"**Boundary residency sweep — \"no emit without sweep\"** (begin emits excepted: nothing has been discussed yet): before EVERY boundary emit, write into its slot each decision, leaning, rejection and citation since the last emit that is not yet file-resident — Decisions (ID opener, `Kind:`), a rule's Mechanism entry (a domain, closure token, residual slot or move disposition settled in conversation and not yet in the entry, an existing entry included), an open question's `Standing recommendation:`, Considered & out, References. A rule left with no entry stays a visible open domain (the \"A rule is captured\" rule).\n\nThe sweep rides this existing boundary trigger — no new prompt, no user-facing step — so the engine-computed attestation counts describe the SWEPT file, and `orbit-audit-drift`'s cross-check closes the loop."},
  {"id":"E-timing-begin-heading","bodies":["orbit-explore"],"kind":"reworded","before":"### BEGIN emit (D-arc Stage D3 — mode-aware)","after":"### BEGIN emit"},
  {"id":"E-timing-begin","bodies":["orbit-explore"],"kind":"reworded","before":"Fire the begin emit immediately after the staging scaffold + `.openspec.yaml` are written, so the trail records the workstream from minute zero (the `premised → exploring` transition). Mode B (new named exploration): the scaffold is empty, so the engine's counts render 0 and the recommendation renders Early; `final_assessment` records the scaffold + the citation decision (cited or declined). Mode C (crystallization): back-fill `explore.md` FIRST, then fire — the engine computes the BACK-FILLED counts, so the trail's first record states true on-disk state, never a knowingly-false zero; this begin emit IS the crystallization's first emit.","after":"Fire the begin emit right after the scaffold and its `.openspec.yaml` are written. Mode C (crystallization): back-fill `explore.md` FIRST, then fire — this begin emit IS the crystallization's first emit.\n\nThe trail then records the workstream from minute zero (the `premised → exploring` transition). In Mode B the scaffold is empty, so the engine's counts render 0 and the recommendation renders Early; `final_assessment` records the scaffold + the citation decision (cited or declined). In Mode C the engine computes the BACK-FILLED counts, so the trail's first record states true on-disk state, never a knowingly-false zero."},
  {"id":"E-timing-retro","bodies":["orbit-explore"],"kind":"reworded","before":"**No retro-fire**: resuming a pre-D3 staging dir that has no emits does NOT retroactively fire a begin emit (add-only, no backdating) — the next boundary emit covers it.","after":"**No retro-fire**: resuming a staging dir that has no emits does NOT retroactively fire a begin emit (add-only, no backdating) — the next boundary emit covers it."},
  {"id":"E-timing-boundary","bodies":["orbit-explore"],"kind":"reworded","before":"Per `orbit-run-summary-emit`'s `Emit timing semantics` requirement, a conversation boundary for multi-turn conversational commands like `/orbit:explore` is EITHER:","after":"A conversation boundary is EITHER:"},
  {"id":"E-timing-rules","bodies":["orbit-explore"],"kind":"reworded","before":"1. **User explicitly signals stop or pause** — \"stop\", \"pause\", \"that's it for now\", \"we'll come back to this later\", or equivalent intent\n2. **AI-initiated wrap** — AI says something like \"I've captured everything; type `/orbit:propose <name>` when ready\" or equivalent intent (an explicit suggestion of the next workflow step)","after":"1. **User explicitly signals stop or pause** — \"stop\", \"that's it for now\", \"we'll come back to this later\", or equivalent intent\n2. **AI-initiated wrap** — AI explicitly suggests the next workflow step (\"I've captured everything; type `/orbit:propose <name>` when ready\")"},
  {"id":"E-timing-wrap","bodies":["orbit-explore"],"kind":"reworded","before":"**Canonical orbit UX convention**: when handing control back to the user after substantive explore work, include an explicit wrap phrase suggesting the next step. This turns the handoff into a rule-2 signal and triggers the emit naturally without needing to predict future user behavior.","after":"**Canonical orbit UX convention**: when handing control back after substantive explore work, end with an explicit wrap phrase suggesting the next step (a rule-2 boundary)."},
  {"id":"E-timing-bare","bodies":["orbit-explore"],"kind":"reworded","before":"Bare-mode `/orbit:explore` (no name) writes ZERO files — exploration without a name is pre-commitment, ephemeral thinking. Emitting before a name exists would pollute project scope and accidentally seed partial changes the user didn't intend to start.","after":"Bare-mode `/orbit:explore` does NOT emit: with no name it writes ZERO files.\n\nExploration without a name is pre-commitment, ephemeral thinking: emitting before a name exists would pollute project scope and accidentally seed partial changes the user didn't intend to start."},
  {"id":"D5a-mechanism","bodies":["orbit-explore"],"kind":"moved","ref":"mechanism-entries.md","start":"The grammar, stated normatively so a parser can be written from it alone:","end":"- INVOKE: applied — fires on every Mechanism entry, since each move line names a member\n```","digest":"c50e00e41bcb7d1c28cd461be59ea556ca050d172ae135325dc5474270bf25ce","lead":" ","after":"\n\nBefore writing or editing a Mechanism entry (a rule captured, an entry swept at a boundary, a resume adding the section), read `references/mechanism-entries.md` and follow it: the grammar, what is MALFORMED, the closure outcomes, the nine moves and two exemplar entries."},
  {"id":"D5b-concluding","bodies":["orbit-explore"],"kind":"moved","ref":"concluding.md","start":"An exploration MAY conclude in nothing, and the record says so","end":"exactly one live entry carries the slot at every point in the cycle.","digest":"0b27a151da6a8d1c5ce1c541bbc72b8aa0eb2c4ada17892e6671ccc000b6e3c5","after":"An exploration MAY conclude in nothing. Conclude, or reopen, only on the user's declared word in a named session: recommend, never infer — if you judge it should stop and the user has not said so, recommend concluding and write nothing. On that word, read `references/concluding.md` and follow it."},
  {"id":"E-modeC-metadata","bodies":["orbit-explore"],"kind":"reworded","before":"On accept, transition to Mode B and back-fill what's been discussed (the minimal `.openspec.yaml` is written as in Mode B).","after":"On accept, read `references/crystallization.md` before writing any file, then transition to Mode B and back-fill what's been discussed (the minimal `.openspec.yaml` is written as `references/new-exploration.md` says)."},
  {"id":"E-crystallization-metadata","bodies":["orbit-explore"],"kind":"reworded","before":"(and the minimal `.openspec.yaml`, as in Mode B)","after":"(and the minimal `.openspec.yaml`, reading `references/new-exploration.md` first)"},
  {"id":"E1-crystallization","bodies":["orbit-explore"],"kind":"moved","ref":"crystallization.md","start":"When the user requests crystallization during a bare-mode explore","end":"inflection-points-surface-consequences conventions.","digest":"5cb404836ecee27e68bd9a45d4c00d32887d3f2263d935c4e716329a33334087","after":"When a bare exploration is about to be named (the user asks to save it under a name, or accepts the Mode C prompt), read `references/crystallization.md` and follow it before writing any file."},
  {"id":"E3-metadata","bodies":["orbit-explore"],"kind":"moved","ref":"new-exploration.md","start":"Mode B/C explorations carry `orbit/explore/<name>/.openspec.yaml`","end":"it carries forward into the change at promotion.","digest":"996776b23c1df4b1043f23eb4f6edc2b9a8ab598101b32f5817b18bcc7e2a8c8","after":"When a new named exploration is scaffolded (Mode B new, or Mode C once confirmed), or a resumed one lacks it, read `references/new-exploration.md` and follow it: the base fields and the `architecture:` citation to offer."},
  {"id":"E2-emit-section","bodies":["orbit-explore"],"kind":"moved","ref":"run-summary-emit.md","start":"## Run-summary emit (named-mode only)\n\n(Per","end":"seed partial changes the user didn't intend to start.","digest":"2922775bb4dc339085ed56b8fafa5cfae71907b8cdc2a14f59affea3eb6d35a8","after":"## Run-summary emit (named-mode only)\n\nNamed-mode `/orbit:explore <name>` emits at BEGIN and at each conversation boundary.\n\n**Boundary residency sweep — \"no emit without sweep\"** (begin emits excepted: nothing has been discussed yet): before EVERY boundary emit, write into its slot each decision, leaning, rejection and citation since the last emit that is not yet file-resident — Decisions (ID opener, `Kind:`), a rule's Mechanism entry (a domain, closure token, residual slot or move disposition settled in conversation and not yet in the entry, an existing entry included), an open question's `Standing recommendation:`, Considered & out, References. A rule left with no entry stays a visible open domain (the \"A rule is captured\" rule).\n\nBefore the session's first run-summary emit, read `references/run-summary-emit.md` and follow it to compose the payload: it holds this step whole, with where its fields are documented. Write the payload to a temp file and invoke:\n\n```bash\norbit emit explore --change <name> --payload <payload-file>\n```\n\n### BEGIN emit\n\nFire the begin emit right after the scaffold and its `.openspec.yaml` are written. Mode C (crystallization): back-fill `explore.md` FIRST, then fire — this begin emit IS the crystallization's first emit.\n\n**No retro-fire**: resuming a staging dir that has no emits does NOT retroactively fire a begin emit (add-only, no backdating) — the next boundary emit covers it.\n\n### Conversation boundary detection\n\nA conversation boundary is EITHER:\n\n1. **User explicitly signals stop or pause** — \"stop\", \"that's it for now\", \"we'll come back to this later\", or equivalent intent\n2. **AI-initiated wrap** — AI explicitly suggests the next workflow step (\"I've captured everything; type `/orbit:propose <name>` when ready\")\n\n**Canonical orbit UX convention**: when handing control back after substantive explore work, end with an explicit wrap phrase suggesting the next step (a rule-2 boundary).\n\n**NOT a boundary** (no emit): AI returning control mid-thought to ask a clarifying question; user tangent and return; AI tool-use sequences within a single turn.\n\n### Bare-mode non-emission\n\nBare-mode `/orbit:explore` does NOT emit: with no name it writes ZERO files."},
  {"id":"R2-composition","bodies":["orbit-explore"],"kind":"reworded","before":"When the user runs `/orbit:propose <name>` and `orbit/explore/<name>/explore.md` exists, propose switches to **consume mode**: reads `explore.md` as authoritative, prompts for Open question handling, generates `proposal.md` / `design.md` / `specs/` / `tasks.md`, and **moves** the staging directory to `orbit/changes/<name>/`. The exploration record persists as historical context alongside the generated artifacts.\n\nThis means: durable capture in explore → seamless promotion to formal change. The user doesn't re-type what was already discussed; the AI doesn't paraphrase what was already decided.\n\nThe Mechanism section travels with the file. A BOUNDED residual's two slots are carried at promotion into the requirement's own text (the owner) and into `design.md`'s Risks (a pointer) — that transfer is `orbit-propose-modifications`' `Mechanism section consumption` (Step 0c.6 of the propose body). A concluded exploration is REFUSED at propose and REOPENED here first (see \"Concluding an exploration\").","after":"`/orbit:propose <name>` consumes `orbit/explore/<name>/explore.md` as authoritative (the propose skill's consume mode) and **moves** the staging directory, siblings included, to `orbit/changes/<name>/`; `orbit-propose-modifications`' `Mechanism section consumption` carries a BOUNDED residual's two slots at promotion (`references/mechanism-entries.md`, closure). A concluded exploration is REFUSED at propose and REOPENED here first (`references/concluding.md`)."},
  {"id":"R3-opening","bodies":["orbit-explore"],"kind":"reworded","before":"The sections below describe orbit-specific additions on top of upstream's \"stance, not workflow\" character. The upstream content above is as `orbit-conventions`' `Generated-file disposition` records it; orbit layers capture affordances, an `explore.md` authoring convention, and three invocation modes that activate when the conversation produces material worth keeping.","after":"Orbit adds to the upstream stance above (as `orbit-conventions`' `Generated-file disposition` records it) capture affordances, an `explore.md` authoring convention and three invocation modes, active once the conversation produces material worth keeping."},
  {"id":"R3-epitome-read","bodies":["orbit-explore"],"kind":"reworded","before":"before a captured artifact names a specific construct, read its actual definition; unverifiable → ask the user or leave a `@review:` marker instead of guessing.","after":"before a captured artifact names a specific construct, read its definition; unverifiable → ask the user or leave a `@review:` marker, never guess."},
  {"id":"R3-modeA","bodies":["orbit-explore"],"kind":"reworded","before":"| Upstream behavior. Conversational think-mode, no file created, no staging directory. |","after":"| Upstream behavior: conversational think-mode, no file, no staging directory. |"},
  {"id":"R3-modeB","bodies":["orbit-explore"],"kind":"reworded","before":"Resolve the name by the re-entry table below (nine cells, four refused). **New** — no staging directory AND no active change of that name: scaffold the six sections AND the minimal `.openspec.yaml` (`references/new-exploration.md`). **Resume** — `orbit/explore/<name>/explore.md` exists with the `exploring` token AND no active change of that name: read the existing file as authoritative; a pre-D2 staging directory lacking `.openspec.yaml` gains it on resume (add-only, citation still optional); a file lacking a `## Mechanism` section gains one (add-only). |","after":"Resolve the name by the re-entry table below. **New**: scaffold the six sections and the `.openspec.yaml` (`references/new-exploration.md`). **Resume**: the existing file is authoritative; one lacking `.openspec.yaml` (citation optional) or `## Mechanism` gains it, add-only. |"},
  {"id":"R3-modeC","bodies":["orbit-explore"],"kind":"reworded","before":"| Prompt the user: \"We have enough material here to capture — what should we call this exploration?\" On accept, read `references/crystallization.md` before writing any file, then transition to Mode B and back-fill what's been discussed (the minimal `.openspec.yaml` is written as `references/new-exploration.md` says). On decline, continue Mode A and don't re-prompt this shape. |","after":"| Prompt: \"We have enough material here to capture — what should we call this exploration?\" On accept, read `references/crystallization.md` before writing any file, then go on as Mode B (metadata per `references/new-exploration.md`), back-filling what's been discussed. On decline, stay in Mode A and don't re-prompt this shape. |"},
  {"id":"R3-reentry-intro","bodies":["orbit-explore"],"kind":"reworded","before":"`/orbit:explore <name>` resolves the name against FOUR facts — a staging directory exists; it is concluded (per the status-header production below; defined only when the directory exists); an active change of that name exists; that change carries an `explore.md` (defined only when the change exists) — as ONE table, nine cells, four refused:","after":"`/orbit:explore <name>` resolves the name against FOUR facts — a staging directory exists; it is concluded (by the status-header production below); an active change of that name exists; that change carries an `explore.md` — in ONE table, nine cells, four refused:"},
  {"id":"R3-reentry-mirror","bodies":["orbit-explore"],"kind":"reworded","before":"| yes | either | yes | either | REFUSED — second claim on one truth; name both paths and stop (neither resume nor scaffold) |\n\n*Mirror of `orbit-explore-modifications`' \"Re-entry resolution and the conclude verb\" — that requirement owns this table; the generated-surface parity test holds this copy byte-equal to it (R-crc-14's mirror corollary).*\n\nOne edge","after":"| yes | either | yes | either | REFUSED — second claim on one truth; name both paths and stop (neither resume nor scaffold) |\n\nOne edge"},
  {"id":"R3-reentry-edge","bodies":["orbit-explore"],"kind":"reworded","before":"One edge the table's second fact implies: a staging directory WITHOUT `explore.md`, or whose header carries neither fixed token, resolves as not-concluded and resumes with the stub or header added (add-only) — never MALFORMED. The status-header production is read on the change-directory file too: a `concluded` header inside `orbit/changes/<name>/explore.md` (a name promoted without reopening) resolves as the third row — state the conclusion and its trigger, reopen only on the user's word — never as a silent resume.","after":"A staging directory WITHOUT `explore.md`, or whose header carries neither token, is not concluded and resumes with the stub or header added (add-only), never MALFORMED. A `concluded` header in `orbit/changes/<name>/explore.md` (a name promoted without reopening) resolves as the third row, never a silent resume."},
  {"id":"R3-metadata-heading","bodies":["orbit-explore"],"kind":"reworded","before":"### Minimal explore metadata (`.openspec.yaml`, D-arc Stage D2)","after":"### Minimal explore metadata (`.openspec.yaml`)"},
  {"id":"R3-six-sections","bodies":["orbit-explore"],"kind":"reworded","before":"When a named exploration exists (Mode B/C), `orbit/explore/<name>/explore.md` follows this structure — SIX sections in this order. The format is `orbit-conventions`' (its requirement keeps its historical title for delta identity; the format it specifies is six). The three productions in this section — the status header, the Decisions entry, the Mechanism entry — are MIRRORS of the productions `orbit-conventions` owns, carried here because a generated skill cannot resolve that spec at runtime; a parity test holds each byte-equal to its owner (R-crc-14's mirror corollary), and every other mention in this body points at them.","after":"A named exploration's `orbit/explore/<name>/explore.md` has SIX sections, in this order (`orbit-conventions`' format). The status-header and Decisions-entry productions are below, the Mechanism-entry production in `references/mechanism-entries.md`; every other mention points at them."},
  {"id":"R3-placeholder-mechanism","bodies":["orbit-explore"],"kind":"reworded","before":"<one entry per live rule in Decisions, keyed by the rule's ID, in the entry grammar of `references/mechanism-entries.md`: the domain as a table, the closure token, the residual slots iff BOUNDED, nine move lines; `### Case <n>` blocks hold the evidence the move lines cite>","after":"<one entry per live rule in Decisions, keyed by its ID, in the grammar of `references/mechanism-entries.md`; `### Case <n>` blocks hold the evidence its move lines cite>"},
  {"id":"R3-placeholder-open","bodies":["orbit-explore"],"kind":"reworded","before":"<things we don't know yet; resolved later by moving to Decisions, deferred as @review: markers via /orbit:propose, or abandoned to Considered & out. EVERY entry carries the slot line `Standing recommendation: <the current leaning verbatim>` — or the literal `Standing recommendation: none yet` when no leaning exists; never an entry with the slot absent (D-arc Stage D5, leak-hardening layer 1)>","after":"<things we don't know yet; moved to Decisions when resolved, deferred as @review: markers via /orbit:propose, or abandoned to Considered & out. EVERY entry carries `Standing recommendation: <the current leaning verbatim>`, or `Standing recommendation: none yet` — never absent>"},
  {"id":"R3-scaffold-after","bodies":["orbit-explore"],"kind":"reworded","before":"When creating a new file, all six sections are scaffolded (empty content under each heading). When resuming, read the existing file as authoritative; a file written before this format, with no `## Mechanism` section, is read and not rejected — the section is added on next touch (a format note, never a blocker).","after":"In a new file all six sections are scaffolded, empty. On resume the existing file is authoritative; one with no `## Mechanism` section is read, not rejected, and gains it on next touch."},
  {"id":"R3-status-mirror","bodies":["orbit-explore"],"kind":"reworded","before":"```\n\n*Mirror of `orbit-conventions`' `explore.md` format requirement (its retained title names the old section count; the format is six sections) — the owner of this production.*\n\n- `> **Status**: exploring. …`","after":"```\n\n- `> **Status**: exploring. …`"},
  {"id":"R3-status-other","bodies":["orbit-explore"],"kind":"reworded","before":"Any other first line is NEITHER token: the file resolves as not-concluded and the header is added on next touch (add-only) — never MALFORMED. A status line is a pointer, not an entry.","after":"Any other first line is NEITHER token: the file resolves as not-concluded and gains the header on next touch (add-only), never MALFORMED. A status line is a pointer, not an entry."},
  {"id":"R3-decisions-intro","bodies":["orbit-explore"],"kind":"reworded","before":"Each Decisions entry is a top-level list item whose opener is the ID slot — the opener every exploration on record already writes, formalized rather than replaced (zero migration). One production. A slot is matched anywhere within the lines that belong to the entry's list item — a lazy-continuation line or a nested bullet both qualify, which is what the optional bullet prefix admits; the ` — ` in the opener is the literal em-dash:","after":"Each Decisions entry is a top-level list item opened by its ID slot. A slot matches anywhere in the entry's list item, a lazy-continuation line or a nested bullet (the optional bullet prefix); the ` — ` in the opener is the literal em-dash:"},
  {"id":"R3-decisions-mirror","bodies":["orbit-explore"],"kind":"reworded","before":"```\n\n*Mirror of `orbit-conventions`' \"Decision entry identity and classification\" — the owner of this production.*\n\n**One claim","after":"```\n\n**One claim"},
  {"id":"R3-decisions-claim","bodies":["orbit-explore"],"kind":"reworded","before":"A Decision is a RULE when it PRESCRIBES or CONSTRAINS how something must be done across a SET of situations — the test is \"in which situations does this apply?\", applied to the claim's NORMATIVE force, never to its grammar. A quantified EMPIRICAL claim (\"heading count has never correlated with readiness under any conditions\") has a logical domain and is a FACT: it describes one world and is falsifiable by evidence. A SCOPE choice (in / out / deferred) is one-off. The test applies PER CLAIM as an authoring rule: an entry carrying more than one claim under obligation is SPLIT by the author into entries with distinct IDs (the rule entry owes a Mechanism entry; the finding carries `Kind: fact`). There are no claim-level identifiers.","after":"A Decision is a RULE when it PRESCRIBES or CONSTRAINS how something must be done across a SET of situations — ask \"in which situations does this apply?\" of its NORMATIVE force, never its grammar. A quantified EMPIRICAL claim (\"heading count has never correlated with readiness\") is a FACT, describing one world, falsifiable by evidence. A SCOPE choice (in / out / deferred) is one-off. The test is PER CLAIM: an entry with more than one claim under obligation is SPLIT into entries with distinct IDs (the rule owes a Mechanism entry; the finding is `Kind: fact`)."},
  {"id":"R3-decisions-kind","bodies":["orbit-explore"],"kind":"reworded","before":"**absent means `rule`.** The demanding default turns an omission into a rule that owes a Mechanism entry (rendered as open by ID once a reader parses it) rather than an invisible escape; opting out is WRITTEN. A rule the author never entered at all remains outside every reader's sight — the stated residual, per `Mechanism entry grammar and accounted closure` (R-crc-10).","after":"**absent means `rule`.** An omission is then a rule owing a Mechanism entry, open to any reader, never an invisible escape; opting out is WRITTEN. A rule never entered stays outside every reader's sight: the stated residual."},
  {"id":"R3-decisions-disposition","bodies":["orbit-explore"],"kind":"reworded","before":"— absent means `live`. ONE meaning for every entry: `live` says the claim STANDS; `superseded` and `assigned` say it does not, and point to what does. Two consequences: a RULE is IN the accounting obligation only while its Kind is rule (or absent) AND its Disposition is live (or absent); a CONCLUDED entry's `Re-entry:` slot is the live one only while its Disposition is live (or absent). Leaving the obligation is a NAMED act — an entry left `live` with a bare prose note (\"overtaken\", \"moot\") is still in it.","after":"— absent means `live`. `live`: the claim STANDS; `superseded`, `assigned`: it does not, pointing to what does. A RULE is IN the accounting obligation only while its Kind is rule (or absent) AND its Disposition live (or absent); a CONCLUDED entry's `Re-entry:` slot is live only while its Disposition is. Leaving the obligation is a NAMED act: an entry left `live` with a prose note (\"overtaken\", \"moot\") is still in it."},
  {"id":"R3-evolution","bodies":["orbit-explore"],"kind":"reworded","before":"- **Resolving an Open question** → move the entry to Decisions with a dated rationale, as an entry with an ID opener and its `Kind:`; acknowledge in chat (\"captured\").\n- **Rejecting a considered option** → move it to Considered & out with brief rationale + date.\n- **New decision emerges** → append to Decisions proactively (with brief chat acknowledgment), with its ID opener and `Kind:`.\n- **A rule is captured** → write its Mechanism entry IN THE SAME SITTING (domain table, closure token, residual slots iff BOUNDED, nine move lines) — or leave the entry with `Kind: rule` and no Mechanism entry as a VISIBLE open domain; never downgrade the Kind to escape the obligation. This is the one statement of that rule; the residency sweep points here.\n- **A rule is replaced or handed to another stage** → its entry gains `Disposition: superseded <ID or pointer>` or `Disposition: assigned <stage-id>`.\n- **A leaning emerges on an open question** (discussed but not yet a decision) → write it into that entry's `Standing recommendation:` slot verbatim — a pending leaning always has a file-resident home; `none yet` is only for questions with no leaning at all.","after":"- **Resolving an Open question** → move it to Decisions (dated rationale, ID opener, `Kind:`); acknowledge in chat (\"captured\").\n- **Rejecting a considered option** → move it to Considered & out (brief rationale + date).\n- **New decision emerges** → append it to Decisions proactively (ID opener, `Kind:`), acknowledging briefly in chat.\n- **A rule is captured** → write its Mechanism entry IN THE SAME SITTING, or leave it `Kind: rule` with no entry, a VISIBLE open domain; never downgrade the Kind to escape the obligation. The residency sweep points here.\n- **A rule is replaced or handed to another stage** → its entry gains `Disposition: superseded <ID or pointer>` or `Disposition: assigned <stage-id>`.\n- **A leaning emerges on an open question** → write it verbatim into its `Standing recommendation:` slot; `none yet` only when there is no leaning."},
  {"id":"R3-capture-table","bodies":["orbit-explore"],"kind":"reworded","before":"| **Convention** | \"we always do X\" / \"let's standardize on…\" | `<topic>_convention.md` at project root (e.g., `naming_convention.md`) | **Offer** — one-sentence offer naming the target file |\n| **Perspective** | User describes a caller/client (\"Claude Desktop calls our MCP server\", \"from the Swift host's POV\") | `orbit/lenses/perspectives.md` | **Offer** |\n| **Critical path** | User describes a critical user flow (\"the typical user flow is…\", \"users typically…\") | `orbit/lenses/critical-paths.md` | **Offer** |\n| **Reference** | URL, file, prior change, prior conversation worth reading later | `explore.md` References section | **Offer** when in doubt; quick add when the relevance is obvious |","after":"| **Convention** | \"we always do X\" / \"let's standardize on…\" | `<topic>_convention.md` at project root (e.g., `naming_convention.md`) | **Offer** |\n| **Perspective** | User describes a caller/client (\"Claude Desktop calls our MCP server\") | `orbit/lenses/perspectives.md` | **Offer** |\n| **Critical path** | User describes a critical user flow (\"the typical user flow is…\") | `orbit/lenses/critical-paths.md` | **Offer** |\n| **Reference** | URL, file, prior change or conversation worth reading later | `explore.md` References | **Offer** when in doubt; quick add when obviously relevant |"},
  {"id":"R3-capture-formats","bodies":["orbit-explore"],"kind":"reworded","before":"The exact file formats — the four-section `<topic>_convention.md` shape (create-vs-append heuristic, contradiction handling) and the `orbit/lenses/perspectives.md` / `critical-paths.md` entry shapes — live in `references/capture-formats.md`; load it when writing an accepted capture.","after":"The file formats (`<topic>_convention.md`'s four sections with create-vs-append and contradictions; the `orbit/lenses/perspectives.md` / `critical-paths.md` entries) are in `references/capture-formats.md`; read it when writing an accepted capture."},
  {"id":"R3-offer","bodies":["orbit-explore"],"kind":"reworded","before":"For **conventions, perspectives, critical paths, and references**: the command offers to capture; the user decides. **Decisions** in named explorations are the exception — they're proactively captured with brief acknowledgment.\n\n**Offer phrasing**: pause briefly and emit a one-sentence offer naming the target file. Example: `That sounds like a convention. Capture in naming_convention.md?`\n\n**Group offers when natural**: when multiple capture-worthy items of the same type emerge in close succession (e.g., three conventions in one paragraph), group them into a single offer rather than asking three times.\n\n**User veto**: if the user says \"don't capture that\" or similar, the proposed capture is not written and the conversation continues unaffected.","after":"For **conventions, perspectives, critical paths and references** the command offers and the user decides; **Decisions** in named explorations are the exception, captured proactively with brief acknowledgment.\n\n**Offer phrasing**: one sentence naming the target file (`That sounds like a convention. Capture in naming_convention.md?`). **Group offers when natural**: one offer for same-type items emerging together. **User veto**: on \"don't capture that\" or similar, nothing is written and the conversation goes on."},
  {"id":"R3-decline","bodies":["orbit-explore"],"kind":"reworded","before":"Within a single conversation, track recent capture declines. If the user has declined a specific convention capture, **don't re-offer** that same convention later in the same conversation. (Tracking is per-conversation; declines don't persist across sessions.)","after":"If the user declines a convention capture, **don't re-offer** that convention later in the same conversation (declines don't persist across sessions)."},
  {"id":"R3-siblings","bodies":["orbit-explore"],"kind":"reworded","before":"The staging directory `orbit/explore/<name>/` can hold additional files beyond `explore.md`:\n\n- `orbit/explore/<name>/sketches/<sketch-name>.md` — design sketches that don't yet warrant being a Decision\n- `orbit/explore/<name>/<draft-convention>.md` — draft convention files that aren't ready to live at project root\n\nThese sibling files persist alongside `explore.md` and move into `orbit/changes/<name>/` together when `/orbit:propose` consumes the exploration.","after":"`orbit/explore/<name>/` can also hold `sketches/<sketch-name>.md` (design sketches, not yet Decisions) and `<draft-convention>.md` (drafts not ready for the project root); they move to `orbit/changes/<name>/` with `explore.md` at `/orbit:propose`."},
  {"id":"R3-capture-decision-row","bodies":["orbit-explore"],"kind":"reworded","before":"| **Decision** (Mode B/C only) | Explicit decision in named exploration | `orbit/explore/<name>/explore.md` Decisions | Auto-capture + brief chat acknowledgment (\"captured\") |\n| **Convention** | \"we always do X\" / \"let's standardize on…\" | `<topic>_convention.md` at project root (e.g., `naming_convention.md`) | **Offer** |","after":"| **Decision** (Mode B/C only) | Explicit decision in a named exploration | `explore.md` Decisions | Auto-capture + brief acknowledgment (\"captured\") |\n| **Convention** | \"we always do X\" / \"let's standardize on…\" | `<topic>_convention.md` at project root | **Offer** |"},
  {"id":"R3-epitome-completeness","bodies":["orbit-explore"],"kind":"reworded","before":"section moves in `explore.md` land whole (a resolved Open question MOVES to Decisions — never left in both); re-read the section after to confirm.","after":"section moves in `explore.md` land whole (a resolved Open question MOVES to Decisions, never left in both); re-read the section to confirm."},
  {"id":"E4-decision-entries","bodies":["orbit-explore"],"kind":"moved","ref":"decision-entries.md","start":"**One claim under obligation per entry.**","end":"an entry left `live` with a prose note (\"overtaken\", \"moot\") is still in it.","digest":"99803ba665db7cf727fae673ec2d8ba31c49012e5fc51e52769b6fcbed8033c6","after":"Before writing the session's first Decisions entry, or stating a concluded exploration's `Re-entry:` trigger, read `references/decision-entries.md` and follow it: whether a claim is a rule, a fact or a scope, when an entry is split, and what each slot means (an absent `Kind:` means `rule`, an absent `Disposition:` `live`)."},
  {"id":"O-R1-disciplines","bodies":["orbit-onboard"],"kind":"reworded","before":"  - **Read-before-reference** (authoring-time): when generating code, specs, or docs that name a specific construct, read the actual definition first. Don't infer the shape from common patterns or training-data conventions.\n  - **Change completeness** (modification-time): substantive modifications to a change-in-flight must apply fully across ALL affected artifacts before being declared done. Known residue MUST NOT be left for a downstream review to catch.\n  - **Pushback** (review-time): verify each flagged issue against current state before acting. Stale findings get reported with evidence and suppressed.\n  - **No-chaining** (turn boundary): the AI invokes at most the orbit workflow commands the user's message explicitly requests — one command per explicit request; it recommends, never invokes, unless the project's `chain` setting grants the next command. Completing a command ends the turn at the position readout and the engine's eligibility line (`Ready when you are:`); gate `passed` means *eligible*, not *commanded*.\n  - **Decision-writing** (call-time): when a setting that reads the records is on, as `orbit decisions status` reports, the AI keeps a record of each call it makes in one of the ledger's areas and of each moment it needs the user — a stop record before such a question, a resolution with the user's answer, a ledger entry after the call (`orbit emit stop`, `orbit emit resolution`, `orbit emit ledger`) — without changing what the user sees or is asked. An answer to a stop already in the trail, or a fix of a record already there, is written whatever `orbit decisions status` reports. A designed prompt (consent, inflection, closure) is a seam, not a stop, and writes nothing.","after":"  - **Read-before-reference** (authoring-time): read a construct's actual definition before naming it in code, specs or docs; never infer its shape from common patterns.\n  - **Change completeness** (modification-time): a modification to a change in flight applies across ALL affected artifacts before it is called done; no known residue is left for a review to catch.\n  - **Pushback** (review-time): verify each flagged issue against current state before acting; stale findings are reported with evidence and suppressed.\n  - **No-chaining** (turn boundary): the AI invokes only the orbit commands the user's message explicitly requests, recommending, never invoking, the next unless the project's `chain` setting grants it; a completed command ends the turn at the position readout and `Ready when you are:` — gate `passed` means *eligible*, not *commanded*.\n  - **Decision-writing** (call-time): while a setting reads them (`orbit decisions status`), the AI records each stop, its resolution and each call in a ledger area (`orbit emit stop`, `orbit emit resolution`, `orbit emit ledger`) without changing what the user sees or is asked; an answer or fix to a record already in the trail is written whatever the setting, and a designed prompt is a seam, not a stop."},
  {"id":"O-tag-architecture-mode","bodies":["orbit-onboard"],"kind":"reworded","before":"(architecture mode — D-arc Stage D2).","after":"(architecture mode)."},
  {"id":"O-tag-program","bodies":["orbit-onboard"],"kind":"reworded","before":"`/orbit:architect` and `orbit architecture status` (D-arc Stage D2): the cross-change","after":"`/orbit:architect` and `orbit architecture status`: the cross-change"},
  {"id":"O-run-summary","bodies":["orbit-onboard"],"kind":"reworded","before":"- **JSON run-summary emission via the engine emit surface** — every editorial and lifecycle command persists a JSON run summary at completion (or per chunk for `/orbit:apply`), COMPOSED AND WRITTEN by `orbit emit <command> --change <name> --payload <file>` (D-arc Stage D5): the AI supplies only the narrative payload plus the required nullable `model` provenance; the engine owns the spine, deterministic facts, computed extensions (explore counts, apply chunk/task arithmetic, `files_touched` diffing), `next_recommended`, filename + collision handling, and a strict write gate (an invalid emit is refused with NO file). Summaries persist to one of FOUR scoped locations: `orbit/changes/<name>/.orbit-runs/` (per-change), `orbit/explore/<name>/.orbit-runs/` (named explorations), `orbit/architecture/.orbit-runs/` (architecture-scoped — `/orbit:architect` and `/orbit:review --as architecture` emits, shared by all docs, never moved by change archiving), and `orbit/.orbit-runs/` (project-wide). The schema follows a universal spine with per-command extensions. (Note: `/orbit:onboard` is one of the few commands that does NOT emit — it's a reference read, not a workflow advancement.)","after":"- **JSON run-summary emission via the engine emit surface** — every editorial and lifecycle command persists a JSON run summary at completion (per chunk for `/orbit:apply`) through `orbit emit <command> --change <name> --payload <file>`: the AI supplies only the narrative payload and the required nullable `model`; the engine owns the spine, the facts and computed extensions (explore counts, apply's task arithmetic, `files_touched`), `next_recommended`, the filename, and a strict write gate that refuses an invalid emit with NO file. Summaries land in one of FOUR places: `orbit/changes/<name>/.orbit-runs/` (per change), `orbit/explore/<name>/.orbit-runs/` (named explorations), `orbit/architecture/.orbit-runs/` (architect sessions and architecture reviews, shared by all docs, never moved by archiving) and `orbit/.orbit-runs/` (project-wide), each a universal spine with per-command extensions. (`/orbit:onboard` is one of the few commands that does NOT emit: it is a reference read.)"},
  {"id":"O-cold-start","bodies":["orbit-onboard"],"kind":"reworded","before":"- **Cold-start orientation** — `orbit status` (bare = the current sprint; `--full` = the whole program) and `orbit status --change <name> --boot` (D-arc Stage D5): ordered artifact pointers in read order, the latest emit per command family with a one-sentence headline, explore-history presence, and the **Touchpoints** view — predicted (design.md's `## Touchpoints` section, authored at propose) before apply commits exist; the diff-computed ACTUAL file map (never prose) once they do. Boot is READ-ONLY and computed fresh per invocation — no hand-maintained handoff files anywhere.","after":"- **Cold-start orientation** — `orbit status` (bare: the current sprint; `--full`: the whole program) and `orbit status --change <name> --boot`: artifact pointers in read order, the latest emit per command family with its headline, explore-history presence, and the **Touchpoints** view — predicted from design.md's `## Touchpoints` before apply commits exist, the diff-computed ACTUAL file map once they do. Boot is READ-ONLY and computed fresh: no hand-maintained handoff files."},
  {"id":"O-propose","bodies":["orbit-onboard"],"kind":"reworded","before":"**Phase 2 — propose (`/orbit:propose <name>`)**: Generates the change artifacts (proposal, design, specs, tasks) from the explore.md (consume mode) or from a prompted description (standalone mode). Consume mode treats `explore.md` as authoritative seed: Premise → proposal motivation; Decisions → spec deltas + design + tasks; Considered & out → design's \"Alternatives considered\"; References → contextual reads. Open questions become per-question prompts during propose with three resolution paths (resolve now → Decision; defer → `@review:` marker in artifacts; abandon → moves to Considered & out). After artifact generation, the staging directory at `orbit/explore/<name>/` moves to `orbit/changes/<name>/` (the historical `explore.md` persists alongside the new artifacts). Emits a completion run summary to `orbit/changes/<name>/.orbit-runs/propose-<TS>.json` (\"T0\" is reserved for review-external's prompt-packaging emit).","after":"**Phase 2 — propose (`/orbit:propose <name>`)**: Generates the change artifacts (proposal, design, specs, tasks) from `explore.md` (consume mode) or from a prompted description (standalone mode). Consume mode treats `explore.md` as authoritative: Premise → proposal motivation; Decisions → spec deltas, design and tasks; Considered & out → design's \"Alternatives considered\"; References → contextual reads. Propose prompts for each Open question: resolve now (a Decision), defer (an `@review:` marker) or abandon (to Considered & out). The staging directory then moves to `orbit/changes/<name>/`, `explore.md` with it, and the run summary goes to `orbit/changes/<name>/.orbit-runs/propose-<TS>.json`."},
  {"id":"O-pr-propose","bodies":["orbit-onboard"],"kind":"reworded","before":"*The PR layer (D-arc Stage D6).* When `pr:` in `orbit/config.yaml` names an active regime, propose is also where the change's **draft PR** opens, so CI runs from day one and the work has an outward window for its whole life. The key takes exactly three values: `never` (the default, and what an absent key means — no PR machinery anywhere, byte-identical to pre-capability behavior), `per-proposal` (every change gets its own `<change-name>` branch and PR), and `per-architecture` (a change CITING an architecture doc rides that doc's shared program branch under one program PR; a change with NO citation falls back to per-proposal, so a standalone change never loses its window). The citation selects the target; the config only selects the regime. With no git remote or no `gh` CLI an active mode degrades to `never` behavior for that invocation and says so in one line — the lifecycle never blocks on the PR layer. READY is orbit's terminus: the archive phase flips the PR ready, and merging it is the user's act.","after":"*The PR layer.* When `pr:` in `orbit/config.yaml` names an active regime, propose is also where the change's **draft PR** opens, so CI runs from day one. The key takes three values: `never` (the default, and what an absent key means: no PR machinery anywhere), `per-proposal` (each change gets its own `<change-name>` branch and PR) and `per-architecture` (a change CITING an architecture doc rides that doc's program branch under one program PR; a change with NO citation falls back to per-proposal). The citation selects the target; the config only selects the regime. With no git remote or no `gh` CLI an active mode degrades to `never` behavior for that invocation and says so in one line — the lifecycle never blocks on the PR layer. READY is orbit's terminus: the archive phase flips the PR ready, and merging it is the user's act."},
  {"id":"O-tag-review","bodies":["orbit-onboard"],"kind":"reworded","before":"pasted verbatim (D-arc Stage D4) — the tail","after":"pasted verbatim — the tail"},
  {"id":"O-address-reviews","bodies":["orbit-onboard"],"kind":"reworded","before":"**Phase 4 — address-reviews (`/orbit:address-reviews <name>` or `--from-file <path>`)**: Walks each finding (or `@review:` marker) through pushback → classify → fix → ripple-cascade → remove-marker. The classification IS the lane (D-arc Stage D4): stale findings suppress with evidence; obvious fixes are previewed compactly at triage then applied without prompts; decision-required findings get a full-prose briefing with chat-directive ratification (a closure prompt is optional and never precedes the briefing); unresolvable findings file as tasks or convert to `@todo:` / `@review(escalated):`. Ripple cascade auto-applies parallel edits to IN-set files (`--no-cascade` opts out); every walk runs finding by finding. **Cross-AI loop**: `/orbit:review`'s reviewer axis reaches a different AI for a second opinion (the review skill states how the prompt reaches it and how its return is saved); the change-scoped walk discovers the saved return, and `--from-file` aims at it explicitly. Detail lives in the address-reviews and review skills (the external handoff in the review skill's `references/external-handoff.md`).","after":"**Phase 4 — address-reviews (`/orbit:address-reviews <name>` or `--from-file <path>`)**: Walks each finding (or `@review:` marker), one by one, through pushback → classify → fix → ripple-cascade → remove-marker. The classification IS the lane: stale findings are suppressed with evidence; obvious fixes are previewed at triage, then applied without prompts; a decision gets a full-prose briefing ratified in chat (a closure prompt is optional and never precedes the briefing); an unresolvable finding is filed as a task or becomes `@todo:` / `@review(escalated):`. Ripple edits to IN-set files apply by default (`--no-cascade` opts out). **Cross-AI loop**: `/orbit:review`'s reviewer axis reaches a different AI for a second opinion (the review skill states how the prompt reaches it and how its return is saved); the change-scoped walk discovers the saved return, and `--from-file` aims at it explicitly (the external handoff is in the review skill's `references/external-handoff.md`)."},
  {"id":"O-system-review","bodies":["orbit-onboard"],"kind":"reworded","before":"**Phase 7 — review (system mode, `/orbit:review <name> --as system`)**: Post-apply review of the whole product state. Pass 0 wraps `orbit-verify-change` (delegated structural check). Passes 1-6: Baseline Compliance (does this change break archived `orbit/specs/` requirements?) / Cohesion (callers/dependents outside the tasks list — signature drift, ripple effects) / Surface Walk (every CLI/MCP/HTTP/public-function surface in `orbit/specs/` still coherent?) / Perspective Reviews (for each named perspective in `orbit/lenses/perspectives.md`, simulate the caller's POV) / Critical-Path Scan (for each flow in `orbit/lenses/critical-paths.md`, walk end-to-end) / Drift / Residue (invokes `/orbit:audit-drift` as a library function). Run summary persists to `.orbit-runs/review-system-<TS>.json`.","after":"**Phase 7 — review (system mode, `/orbit:review <name> --as system`)**: Post-apply review of the whole product state. Pass 0 wraps `orbit-verify-change`. Passes 1-6: Baseline Compliance (does the change break `orbit/specs/` requirements?) / Cohesion (callers and dependents outside the tasks: signature drift, ripples) / Surface Walk (is every CLI/MCP/HTTP/public-function surface in `orbit/specs/` still coherent?) / Perspective Reviews (each caller in `orbit/lenses/perspectives.md`, simulated) / Critical-Path Scan (each flow in `orbit/lenses/critical-paths.md`, walked end-to-end) / Drift / Residue (`/orbit:audit-drift` as a library). Run summary: `.orbit-runs/review-system-<TS>.json`."},
  {"id":"O-pr-archive","bodies":["orbit-onboard"],"kind":"reworded","before":"*The PR layer (D-arc Stage D6).* For a PR-attached change, archive continues past the emit as one designed **tail**: commit the archive's own writes, push, then — PER GRANULARITY — for a per-change PR, rewrite the description into an achievement landmark and flip the PR **READY**; for a PROGRAM PR (a change citing an architecture doc under `pr: per-architecture`), APPEND this stage's entry to the program PR's body and flip NOTHING — stage archives never flip the program PR; its READY flip is the human's act at arc-done, where `/orbit:architect`'s readout surfaces it alongside the merge. **MERGING IS THE USER'S ACT** — READY is orbit's terminus, and no orbit workflow or engine path ever invokes `gh pr merge`. The tail degrades gracefully at every step (no remote, no `gh`, a rejected push) with a one-line note naming what completed and what was skipped; the archive itself never rolls back.","after":"*The PR layer.* For a PR-attached change, archive continues past the emit as one designed **tail**: commit the archive's own writes, push, then — for a per-change PR, rewrite the description into an achievement landmark and flip the PR **READY**; for a PROGRAM PR (a change citing an architecture doc under `pr: per-architecture`), APPEND this stage's entry to the program PR's body and flip NOTHING — stage archives never flip the program PR; its READY flip is the human's act at arc-done, which `/orbit:architect`'s readout surfaces beside the merge. **MERGING IS THE USER'S ACT**: no orbit workflow or engine path invokes `gh pr merge`. The tail degrades gracefully at every step (no remote, no `gh`, a rejected push) with a one-line note of what completed and what was skipped; the archive itself never rolls back."},
  {"id":"O-count","bodies":["orbit-onboard"],"kind":"reworded","before":"The `/orbit:*` command surface — 15 commands.","after":"The `/orbit:*` command surface — 14 commands."},
  {"id":"O-address-reviews-row","bodies":["orbit-onboard"],"kind":"reworded","before":"| `/orbit:address-reviews [<scope>] [--from-file <path>] [--no-cascade]` | Walk inline `@review:` markers or `--from-file` findings (external-review markdown, internal review JSON, or audit-drift JSON — auto-detected by content sniff) through pushback → classify → fix → ripple-cascade → remove. Every walk runs finding by finding; cascade auto-applies to IN-set files by default (`--no-cascade` opts out; OUT-set = audit-trail, baseline specs, cross-change/archive, safe-exclusions). Resolves rather than scans. Aimed at a change, it walks the change's markers, every outstanding pass its reviewed gates report (external returns included) and its unwalked audit-drift emits, one log per source. Decision-lane findings get prose briefings with chat-directive ratification (the closure prompt is optional; no prompt spans several findings). |","after":"| `/orbit:address-reviews [<scope>] [--from-file <path>] [--no-cascade]` | Walk inline `@review:` markers or `--from-file` findings (external-review markdown, internal review JSON or audit-drift JSON, detected by content) finding by finding through pushback → classify → fix → ripple-cascade → remove, ripple edits applying to IN-set files by default (`--no-cascade` opts out). Aimed at a change, it walks the change's markers, every outstanding pass its reviewed gates report (external returns included) and its unwalked audit-drift emits, one log per source. Decision-lane findings get prose briefings ratified in chat. |"},
  {"id":"O-explore","bodies":["orbit-onboard"],"kind":"reworded","before":"Thinking through one change, after architect. The user explores an idea, problem, or comparison; orbit acts as thinking partner. In named mode (`/orbit:explore <name>`), decisions auto-capture to `orbit/explore/<name>/explore.md` in a six-section convention (Premise / Mechanism / Decisions / Open questions / Considered & out / References). In bare mode (no name), the explore stays in conversation until 2+ substantive decisions emerge, then prompts to crystallize a name. Capture triggers also offer to save **lenses** — `perspectives.md` records named callers worth validating from during review (e.g., \"API client\", \"Claude Desktop using MCP\"); `critical-paths.md` records flows worth walking end-to-end (e.g., \"First-time user adds their first device\"). Lenses grow organically; system-mode review Passes 4-5 consult them.","after":"Thinking through one change, after architect, with orbit as thinking partner on an idea, problem or comparison. Named mode (`/orbit:explore <name>`) auto-captures decisions to `orbit/explore/<name>/explore.md`'s six sections (Premise / Mechanism / Decisions / Open questions / Considered & out / References); bare mode stays in conversation until 2+ substantive decisions emerge, then prompts for a name. Capture triggers also offer to save **lenses**: `perspectives.md` records named callers worth validating from during review (e.g., \"API client\"), `critical-paths.md` flows worth walking end-to-end (e.g., \"First-time user adds their first device\"); system-mode review Passes 4-5 consult them."},
  {"id":"O-proposal-review","bodies":["orbit-onboard"],"kind":"reworded","before":"Editorial pre-apply pass over the artifacts — 9 passes from structure/delta integrity through gap hunt to pre-handoff sweep, rolling into a 3-dimension scorecard (Completeness / Correctness / Coherence) with CRITICAL / WARNING / SUGGESTION severities. The run summary persists FIRST via `orbit emit review`; the report is then the ENGINE-RENDERED output of `orbit status --change <name> --report` pasted verbatim — the tail (gate line, position, eligibility) is computed from the gate graph at render time, so the AI never authors a verdict.","after":"The editorial pre-apply pass over the artifacts — 9 passes, from structure and delta integrity through gap hunt to a pre-handoff sweep, scored on Completeness / Correctness / Coherence with CRITICAL / WARNING / SUGGESTION severities. The run summary persists FIRST (`orbit emit review`); the report is then `orbit status --change <name> --report`'s ENGINE-RENDERED output pasted verbatim, its gate line, position and eligibility computed from the gate graph, so the AI never authors a verdict."},
  {"id":"O-apply","bodies":["orbit-onboard"],"kind":"reworded","before":"Implements tasks from `tasks.md` chunk by chunk. Chunks are natural pause points — at each chunk's end, `orbit emit apply` writes the run summary to `.orbit-runs/apply-<TS>.json` — chunk identity, task arithmetic, `files_touched`, and the next recommendation are all engine-computed; the AI supplies only the narrative payload. The user can interrupt between chunks. Apply pauses if a task surfaces a premise problem (e.g., implementation reveals a design issue) and prompts for direction — `@review(escalated):` markers, artifact updates, or scope cuts are all valid responses.","after":"Implements `tasks.md` chunk by chunk; at each chunk's end `orbit emit apply` writes `.orbit-runs/apply-<TS>.json`, its chunk identity, task arithmetic, `files_touched` and next recommendation engine-computed from the AI's narrative payload. The user can interrupt between chunks. A task that surfaces a premise problem (a design issue, say) pauses apply for direction: `@review(escalated):` markers, artifact updates or scope cuts."},
  {"id":"O-archive","bodies":["orbit-onboard"],"kind":"reworded","before":"Moves the change to `orbit/changes/archive/<YYYY-MM-DD>-<name>/` and runs sync-specs (invokes the `orbit-sync-specs` upstream-required primitive) to propagate spec deltas (ADDED/MODIFIED/REMOVED/RENAMED) into baseline at `orbit/specs/`. Pre-archive sweeps: unresolved `@review:` marker check (prompts to address or convert to `@todo:`); audit-drift sweep (runs `/orbit:audit-drift --context pre-archive`). The per-change `.orbit-runs/` directory travels with the change into the archive, preserving the full audit trail. Run summary emits to `.orbit-runs/archive-<TS>.json` inside the archived location.","after":"Moves the change to `orbit/changes/archive/<YYYY-MM-DD>-<name>/` and runs sync-specs (`orbit-sync-specs`) to merge its spec deltas (ADDED/MODIFIED/REMOVED/RENAMED) into the baseline at `orbit/specs/`. Pre-archive sweeps: unresolved `@review:` markers (address, or convert to `@todo:`) and audit-drift (`/orbit:audit-drift --context pre-archive`). `.orbit-runs/` travels with the change, keeping the whole audit trail, and the run summary lands at `.orbit-runs/archive-<TS>.json` inside the archive."},
  {"id":"O-note","bodies":["orbit-onboard"],"kind":"reworded","before":"> **Note on `/orbit:onboard` emit semantics**: this command does NOT emit a run-summary JSON when invoked (composes with `orbit-run-summary-emit` `Emit scope`, which lists `/orbit:onboard` as a non-emit command). `/orbit:onboard` is a single-pass reference read — no workflow state advances, no artifacts produced in user project. Future orbit-additions or refactors MUST preserve this non-emission discipline.\n\nThis skill is the orbit-authored onboarding read for the `/orbit:onboard` slash command. Single-pass; renders Sections 1-5 sequentially.\n\nThis skill is the single source of the onboarding body; the `/orbit:onboard` command is a thin launcher that invokes it.","after":"> **Note on `/orbit:onboard` emit semantics**: this command does NOT emit a run-summary JSON (`orbit-run-summary-emit`'s `Emit scope` lists `/orbit:onboard` as a non-emit command): it is a single-pass reference read that advances no workflow state and produces no artifact in the user's project. Later edits MUST keep it non-emitting.\n\nThis skill is the single source of the `/orbit:onboard` onboarding read; the command is a thin launcher that invokes it. Single-pass: render Sections 1-5 in order."},
  {"id":"O-editorial","bodies":["orbit-onboard"],"kind":"reworded","before":"`/orbit:review` also carries a REVIEWER axis — who runs the pass, including a different AI (codex / fresh Claude / GPT) for a second opinion and a blind pair of two independent passes; its values and their shorthands are the review skill's to state, not this page's. Record vocabulary is frozen across the merge: the packaging emit stays `command: \"review-external\"`, findings stay `external-<as>-<TS>.md`. `/orbit:address-reviews` walks each finding through a structured pushback → classify → fix → ripple-cascade → remove lifecycle (works on both inline `@review:` markers and external-review findings files). Every walk runs finding by finding. Cascade-by-default auto-applies ripple edits to IN-set files (everything outside the four lifecycle-invariant OUT categories); `--no-cascade` opts out.","after":"Its REVIEWER axis says who runs the pass — a different AI (codex / fresh Claude / GPT) for a second opinion, or a blind pair of two independent passes; the review skill states its values and shorthands. Record vocabulary is frozen across the merge: the packaging emit stays `command: \"review-external\"`, findings stay `external-<as>-<TS>.md`. `/orbit:address-reviews` walks each finding, inline `@review:` marker or external-review findings file, one by one through pushback → classify → fix → ripple-cascade → remove, ripple edits applying by default to IN-set files (everything outside the four lifecycle-invariant OUT categories; `--no-cascade` opts out)."},
  {"id":"DW-bullet","bodies":["orbit-apply-change","orbit-archive-change","orbit-architect","orbit-address-reviews","orbit-audit-drift","orbit-continue-change","orbit-explore","orbit-ff-change","orbit-new-change","orbit-propose","orbit-review","orbit-sync-specs","orbit-verify-change"],"kind":"reworded","shared":true,"before":"- **Decision-writing (call-time)**: at each command's first step, and again after this session edits the project config (`orbit/config.yaml` or `.yml`), run `orbit decisions status --json`. On `write: true`, read `references/decision-records.md` and follow its rule for the rest of the command. On `write: false`, write no new ledger entry or stop record; a resolution answering a stop already in the trail, or a replacement fixing a record already there, is still written — read that reference when you write one.","after":"- **Decision-writing (call-time)**: run `orbit decisions status --json` at each command's first step and after this session edits `orbit/config.yaml` (or `.yml`). On `write: true`, follow `references/decision-records.md` for the rest of the command. On `write: false`, write no new ledger entry or stop record; still write a resolution answering a stop already in the trail or a replacement fixing a record there (read that reference first)."},
];

/** Every stage's pairs, each naming its stage, in the order applied. */
export const CUT_PAIRS: CutPair[] = [
  ...CUT_REVIEW_WALK_PAIRS.map((p): CutPair => ({ ...p, stage: 'cut-review-walk' })),
  ...CUT_PROPOSE_ARCHIVE_PAIRS.map((p): CutPair => ({ ...p, stage: 'cut-propose-archive' })),
  ...CUT_EXPLORE_ONBOARD_PAIRS.map((p): CutPair => ({ ...p, stage: 'cut-explore-onboard' })),
];

export const sha = (s: string): string => createHash('sha256').update(s).digest('hex');
const count = (hay: string, needle: string): number => hay.split(needle).length - 1;

type Refs = (dir: string, name: string) => string | undefined;
const skills = getSkillTemplates();
export const skillRefs: Refs = (dir, name) =>
  skills.find((s) => s.dirName === dir)?.template.references?.find((r) => r.name === name)?.content;

/** The span a `moved` pair names in its reference, or why it cannot be read. */
export function movedSpan(p: CutPair, dir: string, refs: Refs = skillRefs): { span: string } | { failure: string } {
  const ref = refs(dir, p.ref!);
  if (ref === undefined) return { failure: `${p.id}: ${dir} ships no references/${p.ref}` };
  for (const a of [p.start!, p.end!]) {
    const n = count(ref, a);
    if (n !== 1) return { failure: `${p.id}: an anchor occurs ${n} times in ${dir}/references/${p.ref}: ${JSON.stringify(a.slice(0, 60))}` };
  }
  const from = ref.indexOf(p.start!);
  const to = ref.indexOf(p.end!);
  if (to < from) return { failure: `${p.id}: the end anchor precedes the start anchor in ${dir}/references/${p.ref}` };
  const span = ref.slice(from, to + p.end!.length);
  if (sha(span) !== p.digest) return { failure: `${p.id}: the span in ${dir}/references/${p.ref} no longer hashes to the digest recorded before the move` };
  return { span };
}

/** Undo one stage's pairs of `dir` on `text`, last applied first; or the first failure. */
function undoStage(dir: string, text: string, stage: CutStage, pairs: CutPair[], refs: Refs): { text: string } | { failure: string } {
  let t = text;
  for (const p of [...pairs].reverse().filter((x) => x.stage === stage && x.kind !== 'retired' && x.bodies.includes(dir))) {
    const n = count(t, p.after);
    if (n !== 1) return { failure: `${dir}: pair ${p.id}'s after occurs ${n} times` };
    let before: string;
    if (p.kind === 'moved') {
      const r = movedSpan(p, dir, refs);
      if ('failure' in r) return r;
      before = (p.lead ?? '') + r.span + (p.trail ?? '');
    } else {
      before = p.before!;
    }
    t = t.replace(p.after, () => before);
  }
  return { text: t };
}

/**
 * Undo every stage's cut pairs of `dir` on `text`, newest stage first, comparing the body with a stage's recorded hash
 * right after that stage's own undo; the text as the oldest stage found it, or the first failure.
 */
export function undoCut(dir: string, text: string, pairs: CutPair[] = CUT_PAIRS, refs: Refs = skillRefs): { text: string } | { failure: string } {
  let t = text;
  for (const stage of [...CUT_STAGES].reverse()) {
    const r = undoStage(dir, t, stage, pairs, refs);
    if ('failure' in r) return r;
    t = r.text;
    const recorded = CUT_RECORDED[stage][dir];
    if (recorded !== undefined && sha(t) !== recorded) return { failure: `${dir}: the undone body does not match its recorded hash (${stage})` };
  }
  return { text: t };
}

/** Why the undo of `dir`'s cut pairs does not reproduce each recorded body, or null. */
export function cutFailure(dir: string, text: string, pairs: CutPair[] = CUT_PAIRS, refs: Refs = skillRefs): string | null {
  const r = undoCut(dir, text, pairs, refs);
  return 'failure' in r ? r.failure : null;
}
